<script setup lang="ts">
import { computed } from 'vue'
import RIcon from '../../replica/RIcon.vue'
import type { PreparationTask } from '../../api/preparationTask'
import { preparationTaskStatusLabels } from '../../api/preparationTask'
const props = defineProps<{ tasks: PreparationTask[]; disabled?: boolean }>()
const emit = defineEmits<{ open: [id: string] }>()
const unscheduled = computed(() => props.tasks.filter(task => !task.content.plannedDate))
const scheduled = computed(() => props.tasks.filter(task => task.content.plannedDate).sort((a, b) => a.content.plannedDate!.localeCompare(b.content.plannedDate!)))
const minutes = computed(() => props.tasks.reduce((total, task) => total + task.content.minutes, 0))
</script>
<template>
  <section class="task-board">
    <div class="task-board-summary"><div><span>本页预计投入</span><strong>{{ minutes }} <small>分钟</small></strong></div><div><span>待安排</span><strong>{{ unscheduled.length }} <small>项</small></strong></div><div><span>已安排</span><strong>{{ scheduled.length }} <small>项</small></strong></div></div>
    <div class="task-board-columns">
      <section class="task-board-column"><h2>待安排 <small>({{ unscheduled.length }})</small></h2><button v-for="task in unscheduled" :key="task.id" class="task-board-item" :disabled="disabled" @click="emit('open', task.id)"><span class="task-board-icon"><RIcon name="code" :size="29" /></span><span><strong>{{ task.content.title }}</strong><small>来源：{{ task.sourceAiTaskId ? '已采用 AI 建议' : '手工创建' }}</small><span class="task-board-meta"><RIcon name="clock" :size="17" />{{ task.content.minutes }} 分钟 · {{ preparationTaskStatusLabels[task.status] }}</span></span><RIcon name="ellipsis" :size="21" /></button><p v-if="!unscheduled.length" class="task-board-empty">本页没有待安排任务</p></section>
      <section class="task-board-column"><h2>已安排 <small>({{ scheduled.length }})</small></h2><div class="task-board-timeline"><button v-for="task in scheduled" :key="task.id" :disabled="disabled" @click="emit('open', task.id)"><time>{{ task.content.plannedDate?.slice(5).replace('-', '.') }}</time><i :class="{ done: task.status === 'DONE' }" /><span><strong>{{ task.content.title }}</strong><small>{{ preparationTaskStatusLabels[task.status] }} · {{ task.content.minutes }} 分钟</small></span></button></div><p v-if="!scheduled.length" class="task-board-empty">选择任务，填写计划日期后显示在这里</p></section>
    </div>
    <footer class="task-board-footer"><p>这里只显示当前页任务，日期和工作量以已保存内容为准。</p><RouterLink to="/prepare/schedule"><RIcon name="calendar-days" :size="17" />查看面试安排<RIcon name="arrow-right" :size="16" /></RouterLink></footer>
  </section>
</template>
